slides = []


def slide(title, body, notes, minute=None, name='', kind='', concept='', exercise_id=None, source=None):
    slides.append(dict(title=title, body=body, notes=notes, start_minute=minute,
                       time=f'{minute // 60}:{minute % 60:02}' if minute is not None else 'Reference',
                       name=name, kind=kind, concept=concept or name, exercise_id=exercise_id, source=source))


def code(source, highlights='all'):
    return f'```python {{{highlights}}}\n{source.strip()}\n```\n'


def table(headers, rows, small=False):
    return '<table class="monitor-table '+('small-table' if small else '')+'"><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'


def flow(items, active=None):
    parts=[]
    for i,(name,description) in enumerate(items):
        reveal=f' v-click="{i}"' if i else ''
        if i:
            parts.append(f'<b{reveal}>→</b>')
        status='muted' if active is not None and i>active else ''
        parts.append(f'<div{reveal} class="{status}">{name}<small>{description}</small></div>')
    return '<div class="pipeline">'+''.join(parts)+'</div>'


def itinerary(rows, caption="Simplified segment IDs for the list operation. Open the notebook for the source reservation, flight numbers, and dates."):
    result = '<div class="itinerary">'
    for label, values in rows:
        result += '<div class="itinerary-row"><div class="itinerary-label">'+label+'</div><div class="segments">'
        for title, detail, status in values:
            result += f'<div class="segment {status}"><strong>{title}</strong><small>{detail}</small></div>'
        result += '</div></div>'
    return result+'</div><div class="itinerary-caption">'+caption+'</div>'


