def exercise(title, step, function, actions, button, check, minute, name, answer=None):
    body=f'<p class="where">Notebook → {step}</p><div class="task-target">Edit {html.escape(function)}</div><ol>'+''.join('<li>'+a+'</li>' for a in actions)+'</ol>'
    body+=f'<div class="done"><b>Run:</b> {button}<br><b>Finished when:</b> {check}</div>'
    if answer:
        body=f'<a class="answer-link" href="/{answer}">Worked answer ↗</a>\n\n'+body
    slide(title,body,'Give participants time to make the change themselves. Have one person point to the input, the changed line, and the observed output. Opening or checking a function sends no model request. Follow the named run control only after the free check passes.',minute,name,'exercise',exercise_id=name)
    slides[-1]['answer']=answer


def capture(key, title, explanation, minute, task):
    receipt=ROOT/'data/native-captures.json'
    records=json.loads(receipt.read_text()).get('captures',[]) if receipt.exists() else []
    record=next((r for r in records if r.get('key')==key),None)
    if not record:
        return
    title=record.get('title',title)
    explanation=record.get('caption',explanation)
    image=ROOT/'public'/record['image'].lstrip('/')
    if not image.is_file() or not record.get('url'):
        raise ValueError(f'Capture {key} has no existing original and source URL')
    crop=record.get('crop')
    image_style=''
    frame_style=''
    annotations=record.get('annotations',[])
    if crop:
        image_style=f'position:absolute;width:{crop["source_width"]/crop["width"]*100}%;height:auto;max-width:none;left:{-crop["x"]/crop["width"]*100}%;top:{-crop["y"]/crop["height"]*100}%;'
        frame_style=f'aspect-ratio:{crop["width"]}/{crop["height"]}'
        annotations=[{**p,'x':(p['x']/100*crop['source_width']-crop['x'])/crop['width']*100,'y':(p['y']/100*crop['source_height']-crop['y'])/crop['height']*100} for p in annotations]
    pins=''.join(f'<span class="native-pin" style="left:{p["x"]}%;top:{p["y"]}%">{i}</span>' for i,p in enumerate(annotations,1))
    notes=''.join(f'<p><b>{i} · {html.escape(p["label"])}</b><br>{html.escape(p["detail"])}</p>' for i,p in enumerate(record.get('annotations',[]),1))
    width=record.get('display_width',760)
    layout='stacked' if record.get('layout')=='stacked' else ''
    columns='1fr' if layout else f'{width}px minmax(0,1fr)'
    body=f'<div class="native-view {layout}" style="grid-template-columns:{columns}"><div class="native-image" style="{frame_style}"><a href="{record["url"]}"><img style="{image_style}" src="/{record["image"].lstrip("/")}" alt="{html.escape(record.get("alt",title))}"></a>{pins}</div><div class="native-notes">{notes}</div></div><p class="caption">{explanation} <a href="{record["url"]}">Open the recorded view ↗</a></p>'
    slide(title,body,task+' Capture identity and original are recorded in data/native-captures.json. This is recorded evidence, not the participant’s live result.',minute,'capture-'+key,source=record['url'])


